function workflowTaskInputToProto(input: WorkflowTaskInput) {
  const result = create(WorkflowTaskSchema);
  if (input.name !== undefined) result.name = input.name;
  result.kind = enumFromString(WorkflowTaskKind, input.kind) as WorkflowTaskKind;
  if (input.export !== undefined) result.export = exportInputToProto(input.export);
  if (input.flow !== undefined) result.flow = flowControlInputToProto(input.flow);
  if (input.compensate !== undefined) result.compensate = input.compensate.map(workflowTaskInputToProto);
  switch (input.kind) {
    case "agent_call":
      if (input.agent_call !== undefined) result.taskConfig = toJson(AgentCallTaskConfigSchema, agentCallTaskConfigInputToProto(input.agent_call)) as JsonObject;
      break;
    case "activity_call":
      if (input.activity_call !== undefined) result.taskConfig = toJson(CallActivityTaskConfigSchema, callActivityTaskConfigInputToProto(input.activity_call)) as JsonObject;
      break;
    case "emit_event":
      if (input.emit_event !== undefined) result.taskConfig = toJson(EmitEventTaskConfigSchema, emitEventTaskConfigInputToProto(input.emit_event)) as JsonObject;
      break;
    case "eval":
      if (input.eval !== undefined) result.taskConfig = toJson(EvalTaskConfigSchema, evalTaskConfigInputToProto(input.eval)) as JsonObject;
      break;
    case "for_each":
      if (input.for_each !== undefined) result.taskConfig = toJson(ForTaskConfigSchema, forTaskConfigInputToProto(input.for_each)) as JsonObject;
      break;
    case "fork":
      if (input.fork !== undefined) result.taskConfig = toJson(ForkTaskConfigSchema, forkTaskConfigInputToProto(input.fork)) as JsonObject;
      break;
    case "grpc_call":
      if (input.grpc_call !== undefined) result.taskConfig = toJson(GrpcCallTaskConfigSchema, grpcCallTaskConfigInputToProto(input.grpc_call)) as JsonObject;
      break;
    case "http_call":
      if (input.http_call !== undefined) result.taskConfig = toJson(HttpCallTaskConfigSchema, httpCallTaskConfigInputToProto(input.http_call)) as JsonObject;
      break;
    case "human_input":
      if (input.human_input !== undefined) result.taskConfig = toJson(HumanInputTaskConfigSchema, humanInputTaskConfigInputToProto(input.human_input)) as JsonObject;
      break;
    case "listen":
      if (input.listen !== undefined) result.taskConfig = toJson(ListenTaskConfigSchema, listenTaskConfigInputToProto(input.listen)) as JsonObject;
      break;
    case "llm_call":
      if (input.llm_call !== undefined) result.taskConfig = toJson(LlmCallTaskConfigSchema, llmCallTaskConfigInputToProto(input.llm_call)) as JsonObject;
      break;
    case "notification":
      if (input.notification !== undefined) result.taskConfig = toJson(NotificationTaskConfigSchema, notificationTaskConfigInputToProto(input.notification)) as JsonObject;
      break;
    case "raise_error":
      if (input.raise_error !== undefined) result.taskConfig = toJson(RaiseTaskConfigSchema, raiseTaskConfigInputToProto(input.raise_error)) as JsonObject;
      break;
    case "run_workflow":
      if (input.run_workflow !== undefined) result.taskConfig = toJson(RunTaskConfigSchema, runTaskConfigInputToProto(input.run_workflow)) as JsonObject;
      break;
    case "set_vars":
      if (input.set_vars !== undefined) result.taskConfig = toJson(SetTaskConfigSchema, setTaskConfigInputToProto(input.set_vars)) as JsonObject;
      break;
    case "switch_case":
      if (input.switch_case !== undefined) result.taskConfig = toJson(SwitchTaskConfigSchema, switchTaskConfigInputToProto(input.switch_case)) as JsonObject;
      break;
    case "transform":
      if (input.transform !== undefined) result.taskConfig = toJson(TransformTaskConfigSchema, transformTaskConfigInputToProto(input.transform)) as JsonObject;
      break;
    case "try_catch":
      if (input.try_catch !== undefined) result.taskConfig = toJson(TryTaskConfigSchema, tryTaskConfigInputToProto(input.try_catch)) as JsonObject;
      break;
    case "validate":
      if (input.validate !== undefined) result.taskConfig = toJson(ValidateTaskConfigSchema, validateTaskConfigInputToProto(input.validate)) as JsonObject;
      break;
    case "wait":
      if (input.wait !== undefined) result.taskConfig = toJson(WaitTaskConfigSchema, waitTaskConfigInputToProto(input.wait)) as JsonObject;
      break;
    default:
      if (input.kind !== undefined && input.kind !== "") {
        throw new Error(`unknown task kind: ${input.kind}`);
      }
  }
  return result;
}

